app.get('/api/cameras/:cameraId/live-events', verifyToken, async (req, res) => {
  const camera = await CameraModel.findOne({ _id: req.params.cameraId, ownerId: req.user.id });
  if (!camera) {
    return res.status(403).json({ error: 'Unauthorized access to target security camera' });
  }

  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive'
  });

  const onMotion = (eventData) => {
    res.write(`event: motion\ndata: ${JSON.stringify(eventData)}\n\n`);
  };

  cameraEventHub.on(`motion:${req.params.cameraId}`, onMotion);
  req.on('close', () => {
    cameraEventHub.off(`motion:${req.params.cameraId}`, onMotion);
  });
});
